info:
Empfängt MQTT-Nachrichten von allen Tenants und schreibt sie in InfluxDB.

Topic-Format: umweltbox/{tenant-id}/{device-id}/{category}/{measurement}
Beispiel: umweltbox/de-hh-privat-peddy/raspi4/environment/temperature

func:
// Topic: umweltbox/{tenant-id}/{device-id}/{category}/{measurement}
const parts = msg.topic.split('/');

if (parts.length !== 5) {
    node.error('Invalid topic (expected 5 levels): ' + msg.topic);
    return null;
}

const [namespace, tenant_id, device_id, category, measurement] = parts;

// Validierung
if (namespace !== 'umweltbox') {
    node.error('Invalid namespace (expected "umweltbox"): ' + namespace);
    return null;
}

// Parse Payload (String oder Object)
let payloadObj = msg.payload;
if (typeof msg.payload === 'string') {
    try {
        payloadObj = JSON.parse(msg.payload);
    } catch (e) {
        // Kein JSON - behandle als einfachen Wert
        payloadObj = { value: parseFloat(msg.payload) };
    }
} else if (typeof msg.payload === 'number') {
    payloadObj = { value: msg.payload };
}

// Extrahiere Value
let value;
if (payloadObj.value !== undefined) {
    value = parseFloat(payloadObj.value);
} else if (typeof payloadObj === 'number') {
    value = payloadObj;
} else {
    node.error('No value found in payload: ' + JSON.stringify(msg.payload));
    return null;
}

if (isNaN(value)) {
    node.error('Invalid value: ' + JSON.stringify(msg.payload));
    return null;
}

// Extrahiere GPS-Koordinaten (wenn vorhanden)
let geoFields = '';
let geoData = null;

if (payloadObj.geo) {
    const geo = payloadObj.geo;

    if (geo.lat !== undefined && geo.lon !== undefined) {
        const lat = parseFloat(geo.lat);
        const lon = parseFloat(geo.lon);

        if (!isNaN(lat) && !isNaN(lon)) {
            geoFields = `,latitude=${lat},longitude=${lon}`;
            geoData = { latitude: lat, longitude: lon };

            // Altitude (optional)
            if (geo.alt !== undefined) {
                const alt = parseFloat(geo.alt);
                if (!isNaN(alt)) {
                    geoFields += `,altitude=${alt}`;
                    geoData.altitude = alt;
                }
            }
        }
    }
}

// Create InfluxDB Line Protocol
// Format: measurement,tag1=value1,tag2=value2 field1=value1,field2=value2 timestamp
const timestamp = Date.now() * 1000000; // nanoseconds
const lineProtocol = `sensors,tenant_id=${tenant_id},device_id=${device_id},category=${category},sensor_type=${measurement} value=${value}${geoFields} ${timestamp}`;

// Prepare message for HTTP request
msg.payload = lineProtocol;
msg.database = 'mintfv'; // Zentrale Datenbank für alle Tenants
msg.url = `http://influxdb:8181/api/v3/write_lp?db=mintfv&precision=ns`;

// Token from environment variable (set in Node-RED settings)
const token = env.get('INFLUXDB_TOKEN');
if (!token) {
    node.error('INFLUXDB_TOKEN not set!');
    return null;
}

msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Content-Type': 'text/plain'
};

// For debugging
msg.meta = {
    tenant_id: tenant_id,
    device_id: device_id,
    category: category,
    sensor_type: measurement,
    value: value,
    geo: geoData,
    topic: msg.topic,
    lineProtocol: lineProtocol
};

return msg;

if (msg.statusCode === 204 || msg.statusCode === 200) {
    node.status({fill:'green',shape:'dot',text:'OK'});
    msg.payload = {
        status: 'success',
        ...msg.meta
    };
} else {
    node.status({fill:'red',shape:'dot',text:'Error ' + msg.statusCode});
    node.error('InfluxDB Error: ' + msg.statusCode + ' - ' + msg.payload);
    msg.payload = {
        status: 'error',
        code: msg.statusCode,
        message: msg.payload
    };
}

return msg;
